extension IconOvenIcon {
    /// The name in the asset catalogue: the raw value, except where Xcode's asset symbols would clash (chat-image -> chat).
    var assetName: String {
        switch self {
        case .chatImage: return "chat-image-symbol"
        case .folderImage: return "folder-image-symbol"
        default: return rawValue
        }
    }
}
